-- 47/52 · Algoritmos — instrucciones paso a paso
--        989 → 1878 caracteres  ·  fuente: mev-content.json
UPDATE public.semanas
   SET contenido = 'Un algoritmo es una secuencia finita de pasos ordenados para resolver un problema o completar una tarea. Es la base de toda la programación.\r\n\r\n**Características de un buen algoritmo:**\r\n- Preciso: cada paso está definido claramente\r\n- Finito: tiene un inicio y un fin (no es infinito)\r\n- Definido: ante las mismas entradas, siempre da el mismo resultado\r\n- Ordenado: los pasos van en secuencia lógica\r\n\r\n**Ejemplo: Algoritmo para preparar un sándwich**\r\n1. Sacar dos rebanadas de pan\r\n2. Poner una rebanada en la mesa\r\n3. Agregar jamón sobre el pan\r\n4. Agregar queso sobre el jamón\r\n5. Poner la segunda rebanada encima\r\n6. Cortar en diagonal\r\n7. Servir en un plato\r\n\r\n**Formas de representar algoritmos:**\r\n\r\n1. **Lenguaje natural:** Pasos escritos en español (como el ejemplo anterior)\r\n\r\n2. **Pseudocódigo:** Mezcla entre lenguaje humano y lenguaje de programación\r\n```\r\nINICIO\r\n  LEER número\r\n  SI número > 0 ENTONCES\r\n    ESCRIBIR ''El número es positivo''\r\n  SINO\r\n    ESCRIBIR ''El número es negativo o cero''\r\n  FIN SI\r\nFIN\r\n```\r\n\r\n3. **Diagrama de flujo:** Representación gráfica con símbolos\r\n- Óvalo: inicio/fin\r\n- Rectángulo: proceso/acción\r\n- Rombo: decisión (sí/no)\r\n- Paralelogramo: entrada/salida de datos\r\n- Flechas: dirección del flujo\r\n\r\n**Ejemplo de algoritmo con decisión:**\r\nAlgoritmo: ¿Debo llevar paraguas?\r\n1. Inicio\r\n2. Ver el pronóstico del clima\r\n3. ¿Hay probabilidad de lluvia mayor al 50%?\r\n   - SÍ → Llevar paraguas\r\n   - NO → No llevar paraguas\r\n4. Salir de casa\r\n5. Fin\r\n\r\n**Los algoritmos están en todos lados:**\r\n- Google usa algoritmos para mostrar resultados de búsqueda\r\n- Netflix usa algoritmos para recomendarte series\r\n- GPS usa algoritmos para encontrar la ruta más corta\r\n- TikTok usa algoritmos para mostrarte videos que te gusten'
 WHERE titulo = 'Algoritmos — instrucciones paso a paso'
   AND contenido LIKE '%'''
   AND length(contenido) < 1878;

-- 48/52 · Seguridad digital y ciudadanía responsable en internet
--        292 → 2056 caracteres  ·  fuente: mev-content.json
UPDATE public.semanas
   SET contenido = 'Internet es una herramienta increíble, pero también tiene riesgos. Saber protegerte es tan importante como saber usarla.\r\n\r\n**Contraseñas seguras:**\r\n- Mínimo 12 caracteres\r\n- Mezcla: mayúsculas + minúsculas + números + símbolos\r\n- NO uses: tu nombre, fecha de nacimiento, 123456, ''password''\r\n- BUENA: M1Perr0_Fid$2025\r\n- USA contraseñas DIFERENTES para cada sitio\r\n- Considera un administrador de contraseñas (Bitwarden es gratuito)\r\n\r\n**Verificación en dos pasos (2FA):**\r\nAdemás de la contraseña, el sitio te pide un código que llega a tu teléfono. Actívalo siempre que se pueda, especialmente en correo y redes sociales.\r\n\r\n**Phishing (suplantación de identidad):**\r\nCorreos o mensajes falsos que parecen de empresas reales (banco, Netflix, gobierno) para robarte datos.\r\n- NUNCA des contraseñas o datos bancarios por correo o mensaje\r\n- Verifica la dirección del remitente (soporte@netflix.com es real, soporte@netf1ix-seguridad.com es falso)\r\n- No hagas clic en enlaces sospechosos\r\n- Los bancos NUNCA piden tu contraseña por correo\r\n\r\n**Huella digital:**\r\nTodo lo que publicas en internet queda registrado. Fotos, comentarios, likes, búsquedas. Antes de publicar algo, pregúntate: ¿me sentiría cómodo si mi futuro jefe viera esto?\r\n\r\n**Ciberbullying:**\r\nAcoso a través de medios digitales. Si lo sufres o lo ves: no respondas al agresor, guarda evidencia (capturas de pantalla), bloquea al agresor, reporta en la plataforma, habla con un adulto de confianza.\r\n\r\n**Información personal que NUNCA debes compartir en línea:**\r\n- Dirección de tu casa\r\n- Número de teléfono (con desconocidos)\r\n- Datos bancarios o de tarjetas\r\n- Contraseñas\r\n- Fotos íntimas\r\n- Tu ubicación en tiempo real\r\n\r\n**Derechos de autor en internet:**\r\n- No todo lo que encuentras en internet es gratis para usar\r\n- Si usas información de un sitio, da crédito (cita la fuente)\r\n- Para imágenes, usa bancos gratuitos: Unsplash, Pexels, Pixabay\r\n- Copiar un texto de internet y ponerlo como tuyo es plagio'
 WHERE titulo = 'Seguridad digital y ciudadanía responsable en internet'
   AND contenido LIKE '%'''
   AND length(contenido) < 2056;

-- 49/52 · El abecedario, números y saludos básicos
--        1207 → 1481 caracteres  ·  fuente: mev-content.json
UPDATE public.semanas
   SET contenido = 'Bienvenido al inglés. Vamos a empezar desde cero con lo más fundamental: el abecedario, los números y cómo saludar.\r\n\r\n**El abecedario en inglés (ABC):**\r\nLas 26 letras son las mismas que en español, pero se pronuncian diferente. Las vocales son especialmente distintas.\r\n\r\nA (éi), B (bi), C (si), D (di), E (i), F (ef), G (yi), H (éich), I (ái), J (yéi), K (kéi), L (el), M (em), N (en), O (óu), P (pi), Q (quiú), R (ar), S (es), T (ti), U (iú), V (vi), W (dóbliu), X (ex), Y (uái), Z (zi)\r\n\r\n**Números del 1 al 20:**\r\n1-one, 2-two, 3-three, 4-four, 5-five, 6-six, 7-seven, 8-eight, 9-nine, 10-ten, 11-eleven, 12-twelve, 13-thirteen, 14-fourteen, 15-fifteen, 16-sixteen, 17-seventeen, 18-eighteen, 19-nineteen, 20-twenty\r\n\r\nDel 21 al 99 se forman: twenty-one (21), thirty (30), forty (40), fifty (50), sixty (60), seventy (70), eighty (80), ninety (90), one hundred (100).\r\n\r\n**Saludos básicos:**\r\n- Hello / Hi — Hola\r\n- Good morning — Buenos días\r\n- Good afternoon — Buenas tardes\r\n- Good evening — Buenas noches (al llegar)\r\n- Good night — Buenas noches (al despedirse)\r\n- Goodbye / Bye — Adiós\r\n- See you later — Hasta luego\r\n- How are you? — ¿Cómo estás?\r\n- I''m fine, thank you — Estoy bien, gracias\r\n- Nice to meet you — Mucho gusto\r\n- What''s your name? — ¿Cómo te llamas?\r\n- My name is... — Mi nombre es...\r\n\r\n**Presentarse:**\r\nHello! My name is María. I am 16 years old. I am from Guadalajara, Mexico. Nice to meet you!'
 WHERE titulo = 'El abecedario, números y saludos básicos'
